const ELEMENTS = [null];
for (const r of ELEMENT_ROWS) {
  const [Z, sym, name, mass, en, rc, ie1, ie2, ea, col, ux, ud, cat, tm, tb, ox] = r;
  ELEMENTS[Z] = { Z, sym, name, mass, en: en || 0, rc, ie1, ie2, ea, color: '#' + col,
    uffR: ux, uffD: ud * 0.0433641, cat, tm: tm || 0, tb: tb || 0, ox,
    metal: cat === 'am' || cat === 'ae' || cat === 'tm' || cat === 'pt' || cat === 'ln' || cat === 'an',
    dblock: cat === 'tm' || cat === 'ln' || cat === 'an' };
}
const Z_MAX = ELEMENTS.length - 1; // the heaviest element there is (120, predicted): no nucleus with more protons is made
const Z_TABLE = 118; // the periodic table and the menus stop at oganesson, the heaviest element ever made
const SYM2Z = {};
for (let z = 1; z < ELEMENTS.length; z++) SYM2Z[ELEMENTS[z].sym] = z;

