  const n0sh = new Float64Array(nsh), n0at = new Float64Array(nat);
  for (let s = 0; s < nsh; s++) { n0sh[s] = el[shAt[s]].shells[shOf[s]].refocc; n0at[shAt[s]] += n0sh[s]; }
