    let msh = new Float64Array(nsh);
    if (opts.qsh0 && opts.qsh0.length === 2 * nsh) for (let s = 0; s < nsh; s++) { qsh[s] = opts.qsh0[s]; msh[s] = opts.qsh0[nsh + s]; }
