function ghostMark(state) { const g = $('dragGhost'); g.classList.toggle('away', state === 'away'); g.classList.toggle('del', state === 'del'); }
function ghostHide() { const g = $('dragGhost'); g.hidden = true; g.innerHTML = ''; }
