  const b = $('speedBtn').getBoundingClientRect(); m.style.left = Math.round(b.left + b.width / 2) + 'px'; m.style.top = Math.round(b.bottom + 6) + 'px';
  m.hidden = false; m.classList.remove('shut'); void m.offsetWidth; m.classList.add('open');
